// Get all previous node outputs
const allInputs = $input.all();

// Get last item which has both previous results
const lastInput = allInputs[allInputs.length - 1];
const prevInput = lastInput.$binary?.data ? JSON.parse(lastInput.$binary.data) : lastInput;

// Load configuration from first node
const agentConfig = prevInput.agentConfig;

// Get users and projects data
const existingUsers = prevInput.users?.result || [];
const existingProjects = prevInput.projects?.result || [];

// Validate required data
if (!agentConfig) {
    throw new Error('Agent configuration not found in input');
}
if (!Array.isArray(existingUsers)) {
    throw new Error('Users list not found in input');
}
if (!Array.isArray(existingProjects)) {
    throw new Error('Projects list not found in input');
}

if (!configInput) {
  throw new Error('Agent configuration input not found');
}
if (!usersInput) {
  throw new Error('Users input not found');
}
if (!projectsInput) {
  throw new Error('Projects input not found');
}

const config = configInput.json.agentConfig;
const existingUsers = usersInput.json.result || [];
const existingProjects = projectsInput.json.result || [];

console.log('📊 Analysis starting...');
console.log('Found ' + existingUsers.length + ' existing users');
console.log('Found ' + existingProjects.length + ' existing projects');

// Create maps for quick lookup
const userMap = new Map(existingUsers.map(u => [u.username, u]));
const projectMap = new Map(existingProjects.map(p => [p.name, p]));

const actions = {
  projectsToCreate: [],
  agentsToCreate: [],
  existingAgents: [],
  stats: {
    totalDepartments: Object.keys(config).length,
    totalAgents: Object.values(config).reduce((sum, dept) => sum + dept.agents.length, 0),
    existingUsers: existingUsers.length,
    existingProjects: existingProjects.length
  }
};

// Generate secure password function with validation
const generatePassword = () => {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*';
  let password = '';
  for (let i = 0; i < 16; i++) {
    password += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  const finalPassword = password + 'Ai1!';

  // Validate password meets requirements
  if (finalPassword.length < 16) {
    throw new Error('Generated password too short');
  }
  if (!/[A-Z]/.test(finalPassword)) {
    throw new Error('Generated password missing uppercase');
  }
  if (!/[a-z]/.test(finalPassword)) {
    throw new Error('Generated password missing lowercase');
  }
  if (!/[0-9]/.test(finalPassword)) {
    throw new Error('Generated password missing numbers');
  }
  if (!/[!@#$%^&*]/.test(finalPassword)) {
    throw new Error('Generated password missing special characters');
  }

  return finalPassword;
};

// Check each department with enhanced error handling
Object.entries(config).forEach(([deptName, deptConfig]) => {
  if (!deptName || !deptConfig) {
    console.log('⚠️ Skipping invalid department: ' + deptName);
    return;
  }

  if (!deptConfig.projectName || !deptConfig.agents) {
    console.log('⚠️ Skipping incomplete department config: ' + deptName);
    return;
  }

  console.log('🔍 Checking department: ' + deptName);

  // Check if project exists
  if (!projectMap.has(deptConfig.projectName)) {
    console.log('   📋 Project needs creation: ' + deptConfig.projectName);
    actions.projectsToCreate.push({
      department: deptName,
      projectName: deptConfig.projectName,
      description: deptConfig.description || (deptName + ' department project')
    });
  } else {
    console.log('   ✅ Project exists: ' + deptConfig.projectName);
  }

  // Check each agent in department with validation
  if (Array.isArray(deptConfig.agents)) {
    deptConfig.agents.forEach(agent => {
      if (!agent || !agent.username || !agent.name) {
        console.log('   ⚠️ Skipping invalid agent in ' + deptName);
        return;
      }

      if (!userMap.has(agent.username)) {
        console.log('   🤖 Agent needs creation: ' + agent.name + ' (' + agent.username + ')');
        try {
          const password = generatePassword();
          actions.agentsToCreate.push({
            ...agent,
            department: deptName,
            projectName: deptConfig.projectName,
            password: password,
            needsUser: true,
            needsProjectAssignment: true
          });
        } catch (err) {
          console.log('   ❌ Failed to generate password for ' + agent.name + ': ' + err.message);
        }
      } else {
        console.log('   ✅ Agent exists: ' + agent.name);
        actions.existingAgents.push({
          ...agent,
          department: deptName,
          kanboardId: userMap.get(agent.username).id
        });
      }
    });
  } else {
    console.log('   ⚠️ No agents array found for department: ' + deptName);
  }
});

console.log('📋 Summary:');
console.log('   Projects to create: ' + actions.projectsToCreate.length);
console.log('   Agents to create: ' + actions.agentsToCreate.length);
console.log('   Existing agents: ' + actions.existingAgents.length);

// Return items properly for n8n workflow
const results = [];

// Add projects that need creation
actions.projectsToCreate.forEach(project => {
  results.push({ json: project });
});

// Add agents that need creation
actions.agentsToCreate.forEach(agent => {
  results.push({ json: agent });
});

// If no items need creation, return a single item with stats
if (results.length === 0) {
  results.push({ json: { noItemsToCreate: true, stats: actions.stats } });
}

return results;

