// Generate comprehensive execution summary
const allResults = $input.all();
const timestamp = new Date().toISOString();

// Count different types of operations
const projectsCreated = allResults.filter(r => r.json.id === 3 && r.json.result).length;
const agentsCreated = allResults.filter(r => r.json.id === 4 && r.json.result).length;
const assignmentsCreated = allResults.filter(r => r.json.id === 6 && r.json.result).length;
const profileTasksCreated = allResults.filter(r => r.json.id === 7 && r.json.result).length;

// Extract department information
const departments = [...new Set(allResults
  .filter(r => r.json.department)
  .map(r => r.json.department))];

// Generate agent credentials summary
const agentCredentials = allResults
  .filter(r => r.json.username && r.json.password)
  .map(r => ({
    username: r.json.username,
    name: r.json.name,
    department: r.json.department,
    email: r.json.email,
    password: r.json.password,
    role: r.json.role
  }));

const summary = {
  executionId: $execution.id,
  timestamp,
  success: true,
  metrics: {
    projectsCreated,
    agentsCreated,
    assignmentsCreated,
    profileTasksCreated,
    departmentsProcessed: departments.length
  },
  departments,
  agentCredentials,
  message: '🚀 AI Agent provisioning completed successfully! Created ' + agentsCreated + ' agents across ' + departments.length + ' departments.',
  nextSteps: [
    "✅ All AI agents are now available in Kanboard",
    "✅ Each agent has a profile task in their department project",
    "✅ Credentials are available in the execution output",
    "✅ Use these credentials in your n8n workflows",
    "🔄 System will check for new agents every 6 hours"
  ]
};

console.log('🎉 EXECUTION SUMMARY:');
console.log('   Projects created: ' + projectsCreated);
console.log('   Agents created: ' + agentsCreated);
console.log('   Assignments created: ' + assignmentsCreated);
console.log('   Profile tasks created: ' + profileTasksCreated);
console.log('   Departments: ' + departments.join(', '));

return [{ json: summary }];
